insert into public.course_keys(course,qid,answer,why) values
  ('academic-writing','q1',0,'''Evaluate'' asks for a judgement supported by evidence, not only description or history.'),
  ('academic-writing','q2',3,'A good thesis takes a clear, arguable position and can be supported across the whole essay.'),
  ('academic-writing','q3',1,'Explanation shows the reader why the evidence matters to the argument, and it is the step students most often skip.'),
  ('academic-writing','q4',3,'Clear topic sentences should together trace the argument, so a mismatch signals a problem in focus or structure.'),
  ('academic-writing','q5',1,'It is precise, avoids vague wording and unsupported claims, and attributes the view to a source.'),
  ('academic-writing','q6',2,'Hedged verbs such as ''suggests'' reflect the strength of the evidence honestly.'),
  ('academic-writing','q7',1,'Paraphrases must be in your own words and structure, and they still need a citation for the idea.'),
  ('academic-writing','q8',0,'Quotations should be used sparingly, for wording that matters, with quotation marks and a page number.'),
  ('academic-writing','q9',0,'Peer-reviewed work has been checked by experts and shows its methods and evidence, unlike unsourced opinion.'),
  ('academic-writing','q10',2,'Each in-text citation should match a full entry in the list so the reader can locate the source.'),
  ('academic-writing','q11',2,'Many Harvard versions include ''Available at'' and an accessed date for web pages, while the APA pattern shown places the date and site name differently. Always follow your institution''s guidance.'),
  ('academic-writing','q12',3,'Editing in layers deals with big problems before surface details, which would otherwise be wasted effort.');
