insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('customer-service-skills','Customer Service Skills','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('customer-service-skills','q1',3,'Listening and checking the real need comes first. Defending the product or guessing a solution before understanding the problem can make things worse.'),
  ('customer-service-skills','q2',0,'A good answer is honest, gives options and ends with a next step. A bare no or a vague maybe leaves the customer with no way forward.'),
  ('customer-service-skills','q3',2,'The best reply is calm, gives the reason and a specific time, and does not copy the anger. Short or sharp replies make the customer feel ignored.'),
  ('customer-service-skills','q4',3,'Customers first need to feel heard, then receive an apology, then a fix, and a follow-up checks that it worked and prevents a repeat.'),
  ('customer-service-skills','q5',3,'Offering a free adjustment with a time is the solution, and promising to message is the follow-up. Acknowledgement and apology also appear in a full response but this part is solve and follow-up.'),
  ('customer-service-skills','q6',0,'A polite no gives a short true reason, an alternative and a next step. Also check consumer rules, since genuinely faulty goods are treated differently.'),
  ('customer-service-skills','q7',1,'Stay calm, set one clear boundary and leave if it continues. Retaliation or public shaming makes things worse and may breach privacy.'),
  ('customer-service-skills','q8',1,'Personal safety comes before any sale. A public place, company and safe handover methods reduce the risk.'),
  ('customer-service-skills','q9',0,'Escalation works when the customer knows what happens next and the manager has the full story, so the customer does not repeat everything.'),
  ('customer-service-skills','q10',1,'Owning a mistake quickly and fixing it fairly protects trust. Hiding it or blaming the customer usually makes the problem bigger.'),
  ('customer-service-skills','q11',0,'Use personal data only for the purpose given and ask permission for other uses. Sharing or posting it breaks the customer''s trust and may break data protection law.'),
  ('customer-service-skills','q12',2,'48 divided by 60 is 0.8, which is 80%.'),
  ('customer-service-skills','q13',2,'The total is 100 + 60 + 30 + 6 + 2 = 198. Dividing by 50 ratings gives 3.96.'),
  ('customer-service-skills','q14',2,'14 / 200 = 7%. 25 / 40 = 62.5%. Reversing the numbers or using the wrong total gives the wrong results.'),
  ('customer-service-skills','q15',1,'60% minus 15% is 45. Use the comments to find what to improve. Asking customers to alter scores would make the data false.');
