insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('cv-interview','CV Writing and Interview Skills','university',70,5,12,true)
insert into public.course_keys(course,qid,answer,why) values
  ('cv-interview','q1',1,'A CV is a short marketing document whose aim is to secure an interview, so it must show relevant fit quickly.'),
  ('cv-interview','q2',2,'It is specific, relevant, evidenced and states the role sought, unlike generic claims.'),
  ('cv-interview','q3',3,'Conventions differ between countries and employers, so check what is asked rather than assuming.'),
  ('cv-interview','q4',1,'It starts with an action verb and gives scale and a result; the others only name a duty or make an unproven claim.'),
  ('cv-interview','q5',0,'Projects, voluntary work and leadership show real skills if described with actions and outcomes, and inventing details is dishonest.'),
  ('cv-interview','q6',0,'Tailoring means putting true, relevant evidence first and matching the employer''s terms where honest.'),
  ('cv-interview','q7',2,'A cover letter adds motivation and targeted evidence rather than repeating the CV.'),
  ('cv-interview','q8',1,'STAR provides a clear, complete structure for behavioural questions.'),
  ('cv-interview','q9',0,'Interviewers need to know what you personally did, though you should still acknowledge the team.'),
  ('cv-interview','q10',2,'Testing and having a backup reduces the risk of disruption and shows professionalism.'),
  ('cv-interview','q11',3,'Honesty combined with a sensible approach shows integrity and problem-solving ability, while invented answers can be exposed.'),
  ('cv-interview','q12',3,'Good questions show interest in the job and its expectations, while others show little preparation or a narrow focus.');
