insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('data-literacy','Reading Data: Tables, Charts and Averages','all',70,6,16,true)
insert into public.course_keys(course,qid,answer,why) values
  ('data-literacy','q1',1,'A share is the part divided by the whole: 3/30 = 0.1, which is 10%.'),
  ('data-literacy','q2',3,'The full circle is 360 degrees, and 25% of 360 is 90.'),
  ('data-literacy','q3',0,'Line charts are designed to show change through ordered points in time.'),
  ('data-literacy','q4',2,'The drawn heights are 6 and 10 units, and 10/6 is about 1.67. The real gap is only about 4%, so the axis exaggerates it.'),
  ('data-literacy','q5',3,'A short window can hide earlier higher values. Asking what came before tests for cherry-picking.'),
  ('data-literacy','q6',0,'The total is 70 + 65 + 80 + 85 = 300, and 300 divided by 4 is 75.'),
  ('data-literacy','q7',2,'The mean is pulled upward by the extreme value. The median is the middle and stays close to what is typical.'),
  ('data-literacy','q8',1,'With four values the median is halfway between the middle two, 5 and 9: (5 + 9)/2 = 7.'),
  ('data-literacy','q9',0,'The mode is the most frequent value. Size 7 appears three times, more than any other size.'),
  ('data-literacy','q10',2,'The range is the highest minus the lowest: 88 - 31 = 57.'),
  ('data-literacy','q11',1,'20% is 0.2, and 0.2 x 4,500 = 900.'),
  ('data-literacy','q12',3,'The change is 20, and 20 divided by the original 80 is 0.25, which is 25%.'),
  ('data-literacy','q13',2,'46 - 40 = 6 points. Relative to the starting 40%, 6/40 = 15%. Percentage points and per cent are different.'),
  ('data-literacy','q14',1,'Correlation does not prove cause. Rainy weather could lead to both more umbrella sales and slower traffic.'),
  ('data-literacy','q15',3,'Choosing people from one unrepresentative place gives a biased result, however many people you ask there.'),
  ('data-literacy','q16',0,'A percentage is meaningless without the starting numbers, the comparison group and the sample size.');
