insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('digital-literacy','Digital Skills for Study and Work','all',70,7,16,true)
insert into public.course_keys(course,qid,answer,why) values
  ('digital-literacy','q1',3,'A good name says what the file is, and a year-month-day date at the start makes files sort in time order.'),
  ('digital-literacy','q2',0,'A PDF keeps the same layout on any device. Removing the extension would stop the file from opening properly.'),
  ('digital-literacy','q3',2,'5 x 4 = 20 MB, and 20 + 7 = 27 MB, which is over 25 MB. A cloud link avoids the limit.'),
  ('digital-literacy','q4',1,'Syncing mirrors changes, including deletions. That is why a sync is not the same as a backup.'),
  ('digital-literacy','q5',2,'Commenters can read and add comments without altering the content.'),
  ('digital-literacy','q6',1,'A link that anyone can use can spread beyond the people you meant. Personal files should go only to named people.'),
  ('digital-literacy','q7',0,'Urgency and a request for your password through a link are typical phishing signs.'),
  ('digital-literacy','q8',3,'Reply all would send your message to 120 inboxes. Only the teacher needs your answer.'),
  ('digital-literacy','q9',1,'Quotation marks tell most search engines to match the exact phrase.'),
  ('digital-literacy','q10',0,'Lateral reading, checking what others say about the claim and the source, is the strongest test.'),
  ('digital-literacy','q11',3,'Information about technology, laws, health and prices can go out of date, even if it was accurate when written.'),
  ('digital-literacy','q12',2,'Changing a few words is not paraphrasing. Using someone''s words or ideas without credit is plagiarism.'),
  ('digital-literacy','q13',0,'References give credit to the original authors and let readers check or follow up the information.'),
  ('digital-literacy','q14',3,'14:00 in Lagos is 13:00 UTC. Nairobi is 3 hours ahead of UTC, so 13 + 3 = 16:00.'),
  ('digital-literacy','q15',1,'Muting reduces background noise for everyone, and chat or hand-raise avoids interrupting.'),
  ('digital-literacy','q16',2,'Styles carry meaning, so the software can build navigation and contents lists and help screen readers. Big bold text is only decoration.');
