insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('digital-marketing-basics','Digital Marketing Basics','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('digital-marketing-basics','q1',2,'Marketing should speak to the person making the decision. Her research showed who that is, so the message, price and timing should fit parents.'),
  ('digital-marketing-basics','q2',1,'A strong call to action is one clear, specific, small step with a timeframe. The others are vague or give too many instructions.'),
  ('digital-marketing-basics','q3',0,'150 divided by 2,000 is 0.075, which is 7.5%. 2,000 divided by 150 is 13.3, which is the wrong way round.'),
  ('digital-marketing-basics','q4',1,'6 divided by 150 is 0.04, so 4%. Interest exists but few buy, so check the offer, price, trust and how fast you reply before spending more on reach.'),
  ('digital-marketing-basics','q5',1,'3,000 divided by 5 is 600 per customer. 1,200 minus 600 leaves 600 profit on each first sale.'),
  ('digital-marketing-basics','q6',0,'Compare cost per customer: 2,400 / 6 = 400 and 3,000 / 10 = 300. B is cheaper per customer despite the higher total.'),
  ('digital-marketing-basics','q7',2,'Permission first, a record of consent and an easy opt-out are the safe principles in every country. Adding people without asking harms trust and may break the law.'),
  ('digital-marketing-basics','q8',2,'Honest advertising means claims about scarcity and deadlines must be true. False pressure misleads customers and damages trust.'),
  ('digital-marketing-basics','q9',3,'A calm public reply shows responsibility, while private messages handle details. Deleting honest complaints or posting fake praise is dishonest.'),
  ('digital-marketing-basics','q10',0,'Soft daylight, a clean background and a sharp focus show the real product. Heavy filters or borrowed photos can mislead customers.'),
  ('digital-marketing-basics','q11',3,'People have the right to decide whether their image is used. Ask first, and for children get a parent or guardian''s clear permission.'),
  ('digital-marketing-basics','q12',2,'3 x 4 = 12 posts. Batching content once a week makes a steady schedule realistic. Consistency usually beats a one-day burst.'),
  ('digital-marketing-basics','q13',0,'30 divided by 500 is 0.06, so 6%. Whether that is good depends on your own history. Over-messaging a permission list harms trust, so change one thing at a time.'),
  ('digital-marketing-basics','q14',1,'Interest exists but conversion is weak, so look at what happens after the click. Changing many things at once hides what caused the change.'),
  ('digital-marketing-basics','q15',3,'Honesty is the common principle, yet details differ between countries and product types. Check your local consumer or advertising authority.');
