insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('english-grammar-essentials','English Grammar and Clear Writing Essentials','all',70,7,16,true)
insert into public.course_keys(course,qid,answer,why) values
  ('english-grammar-essentials','q1',0,'Carefully tells us how they listened, so it describes a verb and is an adverb. Students is a noun, listened a verb, The a determiner.'),
  ('english-grammar-essentials','q2',2,'The subject is the singular box, not pencils, so the singular verb is is correct.'),
  ('english-grammar-essentials','q3',1,'It has one independent clause and one dependent clause starting with because. The others are compound or simple.'),
  ('english-grammar-essentials','q4',3,'The past perfect had started shows the lesson began before the simple past event of arriving.'),
  ('english-grammar-essentials','q5',3,'University begins with a ''yoo'' consonant sound, so a is correct, and Ghana takes no article.'),
  ('english-grammar-essentials','q6',1,'The verb depend always combines with the preposition on.'),
  ('english-grammar-essentials','q7',0,'For a plural noun ending in s, the apostrophe goes after the s. The second option would mean the books of one student.'),
  ('english-grammar-essentials','q8',2,'Its (no apostrophe) is the possessive. It''s means it is or it has, and its'' does not exist.'),
  ('english-grammar-essentials','q9',2,'A semicolon joins two related independent clauses. A comma alone causes a comma splice, and a semicolon should not be followed by and here.'),
  ('english-grammar-essentials','q10',0,'A colon must follow a complete clause, and ''Bring three things'' can stand alone. In the other options the part before the colon is incomplete or the wrong mark is used.'),
  ('english-grammar-essentials','q11',3,'Affect is the verb here. In the second option an affect should be an effect (the noun), and the third has two errors, Two and you''re.'),
  ('english-grammar-essentials','q12',1,'Chairs can be counted, so fewer; space is not counted one by one, so less. Than compares, and the plural chairs needs are.'),
  ('english-grammar-essentials','q13',1,'They''re (they are) going; their books (ownership); over there (place). The other orders mix up the three words.'),
  ('english-grammar-essentials','q14',3,'Two independent clauses are joined by only a comma. The other sentences use a conjunction, a dependent clause or a semicolon correctly.'),
  ('english-grammar-essentials','q15',2,'A topic sentence announces the one main idea of the paragraph. Examples and evidence come in the sentences that follow.'),
  ('english-grammar-essentials','q16',0,'A break and a slow, aloud reading help you notice mistakes. Spelling checkers miss errors like their and there, and sentence variety needs both long and short sentences.');
