insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('entrepreneurship-basics','Starting a Small Business','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('entrepreneurship-basics','q1',2,'250 + 90 + 45 + 35 = 420. The other values leave out or double-count an item.'),
  ('entrepreneurship-basics','q2',0,'Rent stays the same however many customers come. The other items rise and fall with the number of customers.'),
  ('entrepreneurship-basics','q3',3,'600 x 300 = 180000; adding fixed costs 45000 gives 225000. Forgetting the fixed costs, or multiplying them by units, gives the other values.'),
  ('entrepreneurship-basics','q4',1,'Profit 200 / selling price 800 = 25%. The 33.3% figure is the markup, which uses cost as its base.'),
  ('entrepreneurship-basics','q5',0,'Profit 100 / cost 400 = 25%. The 20% is the margin, found by dividing by the price.'),
  ('entrepreneurship-basics','q6',3,'Price = cost / (1 - 0.40) = 360 / 0.6 = 600. Profit is 240, and 240 / 600 = 40%. Adding 40% to cost gives 504, a margin of only 28.6%.'),
  ('entrepreneurship-basics','q7',1,'Contribution = 900 - 600 = 300. 45000 / 300 = 150 units. Dividing by price alone or by cost alone ignores the contribution.'),
  ('entrepreneurship-basics','q8',2,'Break-even units 150 x price 900 = 135,000. Check: costs are 45000 + 150 x 600 = 135,000, equal to the sales.'),
  ('entrepreneurship-basics','q9',1,'Add the target to fixed costs: (45000 + 30,000) / 300 = 250 units.'),
  ('entrepreneurship-basics','q10',3,'New contribution = 900 - 650 = 250. 45000 / 250 = 180. The old figure 150 ignores the cost rise.'),
  ('entrepreneurship-basics','q11',0,'Contribution 120 x 300 = 36000. Subtract fixed costs 45000: -9000, a loss of 9000. Break-even is 150, so 120 is 30 units short.'),
  ('entrepreneurship-basics','q12',2,'A small trial costs little and shows real behaviour. The other choices spend or borrow before you know that people will pay.'),
  ('entrepreneurship-basics','q13',3,'Without records, business and personal money mix and true profit is unknown. A fixed, recorded ''wage'' fixes this. Tax rules differ by country, so that option is not a safe claim.'),
  ('entrepreneurship-basics','q14',0,'84,000 - 51,000 - 9,000 = 24,000. Leaving out the fixed costs gives 33,000.'),
  ('entrepreneurship-basics','q15',1,'14 / 20 = 70%. Saying yes is easier than paying, so a real trial gives better evidence.');
