insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('exam-technique','Exam Technique and Revision Planning','all',70,7,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('exam-technique','q1',2,'6 x 10 = 60 hours in total. 20 percent of 60 is 12, so 60 - 12 = 48 hours remain.'),
  ('exam-technique','q2',1,'Working backwards means you can rebuild the plan quickly. Dropping practice or cramming removes the parts most likely to help.'),
  ('exam-technique','q3',0,'Active recall forces you to retrieve information, which shows gaps. Rereading and copying can feel productive but test little.'),
  ('exam-technique','q4',1,'Spacing gives repeated retrieval over time. The gaps are a guide you can adjust; no exam board requires them.'),
  ('exam-technique','q5',1,'Only 6 of the 18 lost marks (one third) came from missing content. The other 12 came from technique issues that rereading notes will not fix.'),
  ('exam-technique','q6',0,'The learning happens in the diagnosis and redoing. Moving on or memorising answers does not show whether you can handle similar questions.'),
  ('exam-technique','q7',2,'''Explain'' needs reasons linked by words like ''because'' and ''so''. A bare description, a different topic or an unrelated fact does not give reasons.'),
  ('exam-technique','q8',2,'''Evaluate'' asks for a weighed judgement. Description alone or an unsupported opinion does not do that. Check your own board''s definition.'),
  ('exam-technique','q9',3,'The remaining time is 80 minutes. 80 / 60 = 1.33 minutes per mark, and 6 x 1.33 = 8 minutes.'),
  ('exam-technique','q10',3,'70 / 50 = 1.4 minutes per mark, so 5 marks gets 7 minutes. Running over costs marks elsewhere, where easier points may be waiting.'),
  ('exam-technique','q11',3,'Eliminating options improves your chances, and rereading the stem often reveals a deciding word. Always check your own paper''s rules about penalties.'),
  ('exam-technique','q12',3,'55 minutes is 3300 seconds, and 3300 / 40 = 82.5 seconds per question.'),
  ('exam-technique','q13',0,'Targeted, time-limited review plus good preparation and rest is more helpful than an all-night attempt. Giving up wastes the marks you can still earn.'),
  ('exam-technique','q14',0,'A short pause and a switch to a question you can do rebuilds momentum and confidence. Waiting or leaving wastes time you can still use.'),
  ('exam-technique','q15',1,'You cannot change a finished paper, and comparing often increases worry. Using the time to recover and prepare for the next exam is more productive.');
