insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('freelancing-basics','Freelancing and Online Work Basics','all',70,7,16,true)
insert into public.course_keys(course,qid,answer,why) values
  ('freelancing-basics','q1',1,'Freelancers sell services to different clients and manage their own work, prices and records.'),
  ('freelancing-basics','q2',3,'Choose a skill you can do, people will pay for and you can show. Starting narrow makes you easier to hire.'),
  ('freelancing-basics','q3',0,'Real, labelled samples prove ability. Copying or inventing clients is dishonest and can destroy your reputation.'),
  ('freelancing-basics','q4',2,'Clients choose people who understand their problem and show proof. Generic messages are ignored.'),
  ('freelancing-basics','q5',0,'Gross needed is 740 / 0.90 = 822.22. Then 822.22 / 60 = 13.70. 12.33 ignores the set-aside; 18.50 uses 40 hours.'),
  ('freelancing-basics','q6',2,'40 x 0.40 = 16. The rest goes on finding clients, messages, learning and admin, which are unpaid.'),
  ('freelancing-basics','q7',1,'12 x 12 = 144; 25 percent of 144 is 36; 144 + 36 = 180. 169 adds 25 flat, and 144 has no buffer.'),
  ('freelancing-basics','q8',3,'A clear scope lets you handle extra requests fairly. Free extras lower your real rate.'),
  ('freelancing-basics','q9',3,'100 / 14 = 7.14. Fixed prices only pay well when the hours are estimated well.'),
  ('freelancing-basics','q10',0,'Written terms reduce misunderstandings. Local laws vary, so check them and get advice for larger jobs.'),
  ('freelancing-basics','q11',1,'30 percent = 60 and 40 percent = 80, so 60 + 80 = 140. 60 CU remains due at delivery.'),
  ('freelancing-basics','q12',2,'You keep 80 percent, so 100 / 0.80 = 125. Adding 20 gives 120, which leaves you 96. Always check real fees.'),
  ('freelancing-basics','q13',0,'Real employers pay you. Asking you to pay first is a classic scam, whatever the amount.'),
  ('freelancing-basics','q14',1,'Never give logins, PINs or codes to anyone. A genuine client only needs payment details to pay you, never access to your account.'),
  ('freelancing-basics','q15',2,'12 / 3 = 4 days of work, plus 1 buffer day = 5. Promising 4 leaves no room for problems.'),
  ('freelancing-basics','q16',3,'Good records let you answer any question later. Rules differ by country, so check official sources.');
