insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('git-github-basics','Git and GitHub for Beginners','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('git-github-basics','q1',0,'Git keeps a history of commits showing who changed what and when, and branches allow parallel work. It does not edit content or compress files.'),
  ('git-github-basics','q2',1,'Git is the tool that tracks history, and it works offline. GitHub is an online service that stores repositories and adds features such as pull requests.'),
  ('git-github-basics','q3',3,'A clear message states what the commit does. The other messages say nothing about the change.'),
  ('git-github-basics','q4',1,'On GitHub you commit by saving the changes, which asks for a message. Closing the tab loses the edit, and Git commands are not typed into the file editor.'),
  ('git-github-basics','q5',2,'A new file Git has never been told about is shown as untracked. Only after git add does it appear as staged.'),
  ('git-github-basics','q6',0,'Commit saves only what is in the staging area. With nothing staged, Git reports there is nothing to commit. Pushing is a separate step.'),
  ('git-github-basics','q7',2,'You change files, stage them with git add, and then commit the staged snapshot.'),
  ('git-github-basics','q8',1,'Switch -c creates a branch and moves you onto it. Nothing is merged, deleted or pushed.'),
  ('git-github-basics','q9',3,'You merge into the branch you are on, so first switch to main and then merge add-contact into it. Merging main into add-contact does the opposite.'),
  ('git-github-basics','q10',2,'Both versions are shown, and you choose the final text yourself, remove all markers, stage the file and commit. Committing markers leaves a broken file.'),
  ('git-github-basics','q11',3,'A PR is a review and merge proposal on GitHub. Downloading is pull, and a copy under your account is a fork.'),
  ('git-github-basics','q12',1,'The base is where changes will go (main) and the compare branch holds the new changes (improve-readme). Reversing them proposes merging the wrong way.'),
  ('git-github-basics','q13',2,'Git pull downloads and merges new commits from the remote. Push sends your commits up, add stages files, and init creates a new repo.'),
  ('git-github-basics','q14',1,'Remote add creates the link to GitHub and push uploads the branch. Clone is for copying an existing repo.'),
  ('git-github-basics','q15',3,'Git keeps old commits, so deleting a file later does not erase it from history. The secret should be treated as exposed and the password changed.');
