insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('graphic-design-basics','Graphic Design Basics','all',70,7,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('graphic-design-basics','q1',0,'Proximity says related items belong close together. Date, time and place are one group of information and should sit together, with space separating them from the next group.'),
  ('graphic-design-basics','q2',1,'WCAG asks for at least 4.5 to 1 for normal text. Only dark blue passes, by a wide margin. Light grey, yellow and orange on white are too faint, especially outdoors.'),
  ('graphic-design-basics','q3',2,'Hue is the colour family and brightness is light versus dark. Saturation is the intensity: a low-saturation red looks dull or greyish, a high-saturation red looks vivid.'),
  ('graphic-design-basics','q4',3,'Red-green confusion is common, so colour alone must not carry the meaning. Adding words or icons and differing lightness lets everyone read it. Making colours brighter or of equal lightness does not solve the problem.'),
  ('graphic-design-basics','q5',1,'SVG is a vector format built from shapes, so it can be scaled to any size and stay sharp. JPG and PNG are made of pixels and blur when enlarged.'),
  ('graphic-design-basics','q6',0,'JPG compresses photographs to a small file size, which saves data. PNG files of photos are usually much larger, photos are not vector shapes, and PDFs can be opened on phones.'),
  ('graphic-design-basics','q7',2,'The image has far fewer pixels than the page needs, so each pixel is enlarged and the picture becomes blurry or blocky. Stretching does not add detail.'),
  ('graphic-design-basics','q8',3,'Too many fonts look messy and weaken the design''s consistency. One or two fonts with different sizes and weights give variety while keeping repetition.'),
  ('graphic-design-basics','q9',1,'When everything has the same emphasis, the viewer cannot tell what matters most. Use size, weight and colour to rank the content.'),
  ('graphic-design-basics','q10',0,'Being online does not make an image free. Credit alone is not permission, and cropping does not change copyright. Check the licence, especially for commercial use.'),
  ('graphic-design-basics','q11',3,'BY means credit is needed and NC means non-commercial. CC0 and public domain give up the rights, and CC BY allows commercial use with credit.'),
  ('graphic-design-basics','q12',2,'Distance reduces how much detail we can see, so the headline needs size, weight and strong contrast. Thin, pale or decorative text becomes unreadable from far away.'),
  ('graphic-design-basics','q13',3,'Greyscale removes hue and keeps lightness. If the parts blend together, they depend on hue alone, which fails for some colour-blind readers and in poor light. Add a lightness difference.'),
  ('graphic-design-basics','q14',1,'White space gives the eye room to rest and highlights the main items. A consistent margin keeps a layout tidy on any size of screen or paper.'),
  ('graphic-design-basics','q15',2,'Repetition means reusing the same visual elements so all the pieces look like they belong together, which also builds recognition.');
