insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('html-css-basics','Build a Web Page: HTML and CSS','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('html-css-basics','q1',0,'The text in a browser tab comes from the title element inside head. An h1 is drawn inside the page, lang describes the language, and charset sets the character encoding.'),
  ('html-css-basics','q2',0,'Every opened tag must be closed, and in reverse order. The strong tag needs </strong> before </p>.'),
  ('html-css-basics','q3',0,'A link destination belongs in href. Src is for images and similar resources. Relative file names like contact.html are fine.'),
  ('html-css-basics','q4',0,'Alt text replaces the picture when it fails to load and is read by screen readers. It does not change speed, size or file location.'),
  ('html-css-basics','q5',0,'An ordered list shows that sequence matters and numbers the steps automatically. A ul gives bullets with no order, and li belongs inside ul or ol.'),
  ('html-css-basics','q6',1,'Nav is the semantic element for main navigation links. Div has no meaning, aside is for side content, and article is for a self-contained piece such as a news story.'),
  ('html-css-basics','q7',2,'The selector .intro matches class="intro". The element has an id, which needs #intro. Red is a valid colour, so the rule is simply not matching.'),
  ('html-css-basics','q8',3,'When both rules match, the more specific selector wins. A class beats an element name, whatever order the rules are written in.'),
  ('html-css-basics','q9',1,'CSS property names use the American spelling color. Browsers ignore properties they do not recognise.'),
  ('html-css-basics','q10',3,'By default width covers only the content. Add 20px padding on each side (40px) and 5px border on each side (10px): 200 + 40 + 10 = 250px.'),
  ('html-css-basics','q11',2,'Margin is the space outside the border that pushes neighbouring elements away. Padding adds space inside the border.'),
  ('html-css-basics','q12',1,'Flex items line up along the main axis, which is a row by default. Stacking would need flex-direction: column.'),
  ('html-css-basics','q13',0,'Justify-content works along the main axis, which is horizontal in the default row direction, so the items group in the middle.'),
  ('html-css-basics','q14',2,'Without the viewport tag a phone lays out the page at a wide desktop width and shrinks it. The tag tells it to use the real device width.'),
  ('html-css-basics','q15',3,'Min-width: 600px is true only when the screen is 600px or wider. At 400px the rule is not applied, so the default column layout remains.');
