insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('online-safety-cybersecurity','Online Safety and Cybersecurity Basics','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('online-safety-cybersecurity','q1',0,'Leaked passwords are tried on other sites. Unique passwords and two-step verification, beginning with email, limit the damage.'),
  ('online-safety-cybersecurity','q2',1,'Length and uniqueness beat predictable tricks. Names, dates and clubs are guessed first, and reuse spreads one leak to many accounts.'),
  ('online-safety-cybersecurity','q3',2,'Providers do not ask for PINs by SMS. Urgency is a scam tactic, and you should verify through an official channel, not the one the message gives you.'),
  ('online-safety-cybersecurity','q4',3,'Genuine scholarships do not ask winners to pay to receive money. Paying first is a classic advance-fee scam sign.'),
  ('online-safety-cybersecurity','q5',0,'Asking applicants for money up front is a standard fake-job sign, and photos or IDs are easy to fake.'),
  ('online-safety-cybersecurity','q6',0,'Public networks are not controlled by you. Sensitive logins are safer on mobile data.'),
  ('online-safety-cybersecurity','q7',1,'Apps should only get what they need for their job. Unnecessary permissions are a warning sign.'),
  ('online-safety-cybersecurity','q8',2,'These are signs of a SIM swap. Quick contact with the provider and bank limits what the attacker can do.'),
  ('online-safety-cybersecurity','q9',3,'A one-time code is the key to your account. Staff never need you to read it out, and knowing your name proves nothing.'),
  ('online-safety-cybersecurity','q10',0,'Fake wrong-transfer messages are a known trick, so verify with the provider and let them handle genuine reversals.'),
  ('online-safety-cybersecurity','q11',1,'Regaining control, securing the connected email and warning contacts stops further harm. Paying a ''recovery'' offer is usually a second scam.'),
  ('online-safety-cybersecurity','q12',0,'Recovery details control access to the account, so attackers who change them can retake it later.'),
  ('online-safety-cybersecurity','q13',2,'Not joining in, supporting the person and reporting is the right way to help. Forwarding spreads the harm.'),
  ('online-safety-cybersecurity','q14',3,'Evidence plus reporting and adult support gives the best chance of stopping the bullying; deleting everything removes proof.'),
  ('online-safety-cybersecurity','q15',1,'Phones are lost, broken and stolen. A backup in a different place keeps the work safe, and a copy on the same device does not.');
