insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('personal-finance','Personal Finance and Budgeting','all',70,6,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('personal-finance','q1',2,'Expenses total 76,000. 85,000 - 76,000 = 9,000. The other values omit items or add instead of subtract.'),
  ('personal-finance','q2',0,'20% of 120,000 = 24,000. 60,000 is the 50% needs share and 36,000 is the 30% wants share.'),
  ('personal-finance','q3',3,'The method is a starting point. Rent and food may already take more than 50% in some places, so a personal plan is better than copying percentages.'),
  ('personal-finance','q4',1,'Target = 3 x 45,000 = 135,000. 135,000 / 9,000 = 15 months.'),
  ('personal-finance','q5',0,'Interest = 20,000 x 0.06 x 4 = 4,800. 5,249.54 is the compound figure and 24,800 is the total, not the interest.'),
  ('personal-finance','q6',3,'20,000 x 1.06^4 = 25,249.54. The 24,800.00 figure is simple interest.'),
  ('personal-finance','q7',1,'Compound interest 5,249.54 - simple interest 4,800 = 449.54.'),
  ('personal-finance','q8',2,'Cost = 9,200 - 8,000 = 1,200. 1,200 / 8,000 = 15%. Dividing by the repayment gives 13.0%, which uses the wrong base.'),
  ('personal-finance','q9',1,'8,000 x 1.15^4 = 13,992.05. Adding the fee four times (simple) gives 12,800, which ignores that the fee itself is charged again.'),
  ('personal-finance','q10',3,'Total repaid = 4,000 x 12 = 48,000; minus 36,000 borrowed = 12,000. 48,000 is the total repaid, not the extra cost.'),
  ('personal-finance','q11',0,'800 x 1.05 = 840; x 1.05 again = 882. Adding 5% twice to the original (880) misses that the second rise applies to the new price.'),
  ('personal-finance','q12',2,'New price = 600 x 1.25 = 750. 12,000 / 750 = 16. Before the rise you could buy 20.'),
  ('personal-finance','q13',3,'Asking for fees first, secrecy and urgency are classic scam signs. Never share a PIN, and contact the real organisation on your own.'),
  ('personal-finance','q14',0,'350 x 26 = 9,100. Small daily amounts add up, which is why records are useful.'),
  ('personal-finance','q15',1,'36,000 / 90,000 = 40%. Dividing by the remaining amount gives 67%, using the wrong base.');
