insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('public-speaking','Public Speaking and Presentation Skills','all',70,7,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('public-speaking','q1',1,'Light preparation plus calming breathing builds confidence. Perfection is not the goal, and feeling nervous is normal.'),
  ('public-speaking','q2',3,'Slow breathing with a longer breath out is a simple way to steady yourself; fast or held breaths do not help.'),
  ('public-speaking','q3',0,'Audience and purpose shape the choice of words, examples and call to action, even for the same topic.'),
  ('public-speaking','q4',2,'A clear purpose guides every other choice in the talk. Design and jokes come later.'),
  ('public-speaking','q5',2,'A strong opening gains attention and states the purpose. Apologising lowers the audience''s confidence.'),
  ('public-speaking','q6',0,'Three points are easy to follow and remember; trying to cover everything overloads listeners.'),
  ('public-speaking','q7',3,'5 minutes × 130 words per minute = 650 words. The other figures correspond to different time lengths.'),
  ('public-speaking','q8',1,'A specific, true example is easy to picture and remember. Vague claims do not stick.'),
  ('public-speaking','q9',1,'Slides should support you, not compete with you. One idea with a picture helps the audience listen.'),
  ('public-speaking','q10',3,'Rushing is common when nervous. Pauses help ideas land and give you time to breathe.'),
  ('public-speaking','q11',0,'Key-word notes allow eye contact. Looking at different people helps the audience feel included.'),
  ('public-speaking','q12',2,'Honesty builds trust. Guessing can mislead people, and rudeness damages your credibility.'),
  ('public-speaking','q13',3,'Restating confirms the question for you and for everyone who missed it, which makes the answer more useful.'),
  ('public-speaking','q14',1,'Looking at the lens feels like eye contact to viewers, and checking technology early prevents avoidable problems.'),
  ('public-speaking','q15',0,'Focusing on one improvement at a time makes practice manageable and builds on what already works.');
