insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('python-next-steps','Python Next Steps: Data and Files','all',70,7,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('python-next-steps','q1',0,'d.get("b", 5) returns the default 5 because "b" is not a key, and d["a"] is 1, so 5 + 1 = 6.'),
  ('python-next-steps','q2',1,'A set keeps each value once, so the six numbers become the three values 1, 2 and 3. len gives 3.'),
  ('python-next-steps','q3',2,'split(",") cuts at every comma. Two commas in a row leave an empty string between them, so the empty item is kept.'),
  ('python-next-steps','q4',3,'The comma after the colon in an f-string format adds thousands separators to the whole number.'),
  ('python-next-steps','q5',2,'Values read from a file are strings, and adding strings joins them. To get 75 you must convert each with int() first.'),
  ('python-next-steps','q6',3,'print("A") runs, then int("z") fails, so print("B") is skipped and the except block prints C. The finally block always runs, so D is printed last.'),
  ('python-next-steps','q7',0,'range(6) gives 0 to 5. The if keeps only odd numbers 1, 3 and 5, and each is doubled, giving 2, 6 and 10.'),
  ('python-next-steps','q8',1,'Mode "w" truncates the file when it is opened, so the second run replaces the first run''s line. Mode "a" would have given 2 lines.'),
  ('python-next-steps','q9',3,'The & operator gives the items found in both sets: 2 and 3. sorted returns a list.'),
  ('python-next-steps','q10',2,'Tuples cannot be changed after they are made, so assigning to point[0] raises TypeError. A list would allow it.'),
  ('python-next-steps','q11',0,'The loop visits each key and value in turn. The values 10, 20 and 30 are added into total, giving 60.'),
  ('python-next-steps','q12',1,'Subtracting two dates gives a timedelta and .days is the number of days. February 2026 has 28 days because 2026 is not a leap year, so 1 February to 1 March is 28 days.'),
  ('python-next-steps','q13',2,'Sorted, the values are 1, 3, 7, 9. With an even count the median is the mean of the two middle values: (3 + 7) / 2 = 5.0.'),
  ('python-next-steps','q14',0,'open() raises FileNotFoundError when the file is missing. The other errors belong to bad conversions, missing dictionary keys and dividing by zero, so they would not catch it.'),
  ('python-next-steps','q15',3,'strip() removes the spaces and title() capitalises the first letter, giving Ama. The f-string then evaluates 1 + 2 inside the braces, so the output is Ama 3.');
