insert into public.course_keys(course,qid,answer,why) values
  ('research-skills','q1',0,'It is focused, names the group and measurable ideas, and cannot be answered by a simple yes or no. The others are vague or loaded.'),
  ('research-skills','q2',1,'Narrowing by group, place and aspect makes the topic manageable.'),
  ('research-skills','q3',2,'A primary source is first-hand evidence. The others interpret or summarise it, so they are secondary.'),
  ('research-skills','q4',3,'It has authority, date, evidence and low commercial bias.'),
  ('research-skills','q5',0,'The company gains from your belief, so bias is likely. It can still show what the company claims.'),
  ('research-skills','q6',1,'The best paraphrase uses new wording and structure and cites the author. The others copy, nearly copy, or claim the work as your own.'),
  ('research-skills','q7',2,'Presenting exact words as your own is plagiarism, even for a few sentences.'),
  ('research-skills','q8',3,'This is the Harvard pattern: author, year without a full stop after the bracket, title, place and publisher. The second option is APA.'),
  ('research-skills','q9',0,'APA uses ''&'', no quotation marks around the article title, and page numbers without ''pp.''. The second option is Harvard.'),
  ('research-skills','q10',1,'Both Harvard and APA lists are in alphabetical order by surname.'),
  ('research-skills','q11',2,'''n.d.'' means no date, and both styles use it.'),
  ('research-skills','q12',3,'It asks one clear thing with neutral answer choices. The others lead the respondent.'),
  ('research-skills','q13',0,'It gives the number, the total and the percentage, and limits the claim to those surveyed.'),
  ('research-skills','q14',1,'Informed, voluntary consent is the base of ethical research.'),
  ('research-skills','q15',2,'Without names, and with only group totals, individuals cannot be identified.'),
  ('research-skills','q16',3,'An outline organises evidence around the question. Dropping unwelcome findings is dishonest.');
