insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('sql-basics','SQL Basics: Working with Data','all',70,6,14,true)
insert into public.course_keys(course,qid,answer,why) values
  ('sql-basics','q1',0,'Prices above 120 are Book (350), Bag (2500) and Ruler (150). ORDER BY price sorts from smallest to largest, giving Ruler, Book, Bag.'),
  ('sql-basics','q2',1,'DESC sorts the largest price first: Bag (2500), Book (350), Ruler, Pen. LIMIT 2 keeps the first two.'),
  ('sql-basics','q3',2,'Pen (100) and Ruler (150) are below 200, so the count is 2. WHERE filters first, then COUNT counts the remaining rows.'),
  ('sql-basics','q4',3,'LIKE ''B%'' matches names starting with B: Book (350) and Bag (2500). Their sum is 2850.'),
  ('sql-basics','q5',0,'The largest price is 2500 and the smallest is 100, so the difference is 2400.'),
  ('sql-basics','q6',1,'GROUP BY makes one group per category and SUM adds the qty in each: Food 5 + 3 = 8, Home 2, School 10 + 4 = 14.'),
  ('sql-basics','q7',2,'HAVING filters the groups after summing. Food totals 8 and School totals 14, both above 5. Home totals only 2, so it is removed.'),
  ('sql-basics','q8',3,'COUNT(*) counts all five rows. COUNT(DISTINCT category) counts the different categories, which are Food, School and Home: three.'),
  ('sql-basics','q9',0,'An inner JOIN keeps only students with a matching fee row. Kojo has none, so he is left out. Ngozi appears twice, once for each of her fees, sorted by amount.'),
  ('sql-basics','q10',1,'The LEFT JOIN keeps every student and fills the fee columns with NULL when there is no match. Only Kojo has no fees, so only he passes the IS NULL test.'),
  ('sql-basics','q11',2,'After the join, Ngozi has two rows (500 and 200) that sum to 700, and Aisha has 700. Kojo has no rows, so he does not appear. The groups are sorted by name.'),
  ('sql-basics','q12',3,'WHERE id > 1 selects phones 2 and 3 only, so each of their prices rises by 50. Phone 1 stays at 100.'),
  ('sql-basics','q13',0,'DELETE without WHERE removes every row in the table. The correct command is DELETE FROM phones WHERE id = 2; and it is wise to check with a SELECT using the same WHERE first.'),
  ('sql-basics','q14',1,'Storing each fact once and linking tables with foreign keys avoids repeated, inconsistent data. The other designs repeat or pack data, which makes searching and correcting it difficult.');
