insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('statistics-basics','Introduction to Statistics','all',70,7,16,true)
insert into public.course_keys(course,qid,answer,why) values
  ('statistics-basics','q1',0,'The 40 chosen students are a part of the whole group, so they are a sample. The 600 students are the population.'),
  ('statistics-basics','q2',2,'Time can take any value in a range, so it is continuous. Goals are counted in whole numbers (discrete), language is nominal categorical, and the rating is ordinal categorical.'),
  ('statistics-basics','q3',1,'Relative frequency is frequency divided by total: 6 / 20 = 0.30, which is 30%.'),
  ('statistics-basics','q4',3,'Favourite sport is categorical, so separate bars are used. Histograms are for grouped continuous data and line graphs for change over time.'),
  ('statistics-basics','q5',3,'The sum is 30 and n = 5, so the mean is 6. In order the data is 2, 3, 5, 8, 12, so the median is the middle value, 5.'),
  ('statistics-basics','q6',1,'The extreme value pulls the mean up strongly because it uses every value. The median depends on the middle of the ordered list, so it hardly moves.'),
  ('statistics-basics','q7',0,'The mode is the most frequent value. 7 appears three times, 4 appears twice and the others once. The number 5.75 is the mean.'),
  ('statistics-basics','q8',2,'Q1 = (5 + 6) / 2 = 5.5 and Q3 = (11 + 12) / 2 = 11.5, so IQR = 11.5 - 5.5 = 6. The number 11 is the range and 8.5 is the median.'),
  ('statistics-basics','q9',2,'The range depends only on the highest and lowest values. The IQR looks at Q3 - Q1, so a single extreme value at either end has little effect.'),
  ('statistics-basics','q10',0,'A larger standard deviation means values lie further from the mean on average. The means are equal, and the standard deviations say nothing about class size.'),
  ('statistics-basics','q11',3,'The mean is 5, deviations are -2, -2, 2, 2, squares are 4, 4, 4, 4, sum 16, variance 16 / 4 = 4, and the square root is 2. The number 4 is the variance.'),
  ('statistics-basics','q12',1,'The complement rule gives P(not rain) = 1 - 0.3 = 0.7. Probabilities cannot be more than 1, so 1.3 is impossible.'),
  ('statistics-basics','q13',1,'The events are independent, so multiply: 1/2 x 1/6 = 1/12. Adding the probabilities would give 2/3, which is wrong, because we need both to happen.'),
  ('statistics-basics','q14',3,'Red and blue cannot happen together, so add: 5/10 + 3/10 = 8/10 = 4/5.'),
  ('statistics-basics','q15',2,'40 to 80 is within 2 standard deviations of the mean (60 +/- 20), which holds about 95% of values under the 68-95-99.7 rule.'),
  ('statistics-basics','q16',0,'Larger random samples vary less around the true mean. They cannot guarantee an exact match, and they do not fix bias caused by poor sampling methods.');
