insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('teamwork-leadership','Teamwork and Leadership Skills','all',70,7,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('teamwork-leadership','q1',3,'Naming tasks, owners and dates solves the real problem, which is unclear responsibility. Waiting or doing everything yourself leaves the cause untouched.'),
  ('teamwork-leadership','q2',2,'A strong goal is specific, has a deadline and can be checked. The others are vague and cannot be judged as met or not met.'),
  ('teamwork-leadership','q3',3,'An action needs a person, a task and a date. Without them, everyone assumes someone else will do it.'),
  ('teamwork-leadership','q4',1,'A chair''s job is to give everyone a fair chance to contribute. Loudness is not the same as quality of ideas, but removing someone is an overreaction.'),
  ('teamwork-leadership','q5',1,'Fair means matching load to real availability, discussed openly. 26 divided by 3 is about 8.7. Ignoring the difference or hiding it causes problems later.'),
  ('teamwork-leadership','q6',3,'Using strengths is good, but fairness means checking that one person does not carry a disproportionate load.'),
  ('teamwork-leadership','q7',0,'Useful feedback is specific, names a strength, points to one issue and suggests a next step. Vague or personal comments do not help the person improve.'),
  ('teamwork-leadership','q8',1,'Listening and asking questions lets you learn from the feedback without letting emotion drive the reply. You can still decide later what to accept.'),
  ('teamwork-leadership','q9',0,'A private, calm conversation about behaviour, with a real question, often solves the problem. Public blame damages trust. Asking a teacher may be needed later if talking fails.'),
  ('teamwork-leadership','q10',0,'An ''I'' statement describes your experience and the effect, rather than judging the other person, so it is less likely to start a defensive argument.'),
  ('teamwork-leadership','q11',1,'Plain language, checking understanding and alternative ways to contribute include everyone. Silence does not reliably mean agreement.'),
  ('teamwork-leadership','q12',0,'Leadership without a title is about helping the group move forward through suggestions, inclusion and follow-up, not claiming authority.'),
  ('teamwork-leadership','q13',3,'Good delegation states the outcome, the deadline and the support available. Vague requests lead to wrong or late work.'),
  ('teamwork-leadership','q14',2,'Asking first finds the real cause, which may be simple confusion. Silent takeover or public blame does not solve the underlying issue.'),
  ('teamwork-leadership','q15',2,'Strong reflection names facts, your own part and a specific action. Vague promises or blaming others give you nothing to change.');
