insert into public.courses(slug,title,level,pass_mark,lesson_count,quiz_count,active) values ('time-management','Time Management and Productivity for Students','all',70,7,15,true)
insert into public.course_keys(course,qid,answer,why) values
  ('time-management','q1',2,'A useful goal has a target, a deadline and a weekly action so you can tell whether you are on track.'),
  ('time-management','q2',0,'Exam revision supports your goals, but it is not yet due. Scheduling it early stops it becoming a panic later.'),
  ('time-management','q3',3,'Notifications demand quick attention, but they rarely help your goals. The others are important for results.'),
  ('time-management','q4',1,'13 × 45 = 585 minutes, which is 585 ÷ 60 = 9.75 hours.'),
  ('time-management','q5',0,'Sleep is 8 × 7 = 56. School is 7 × 5 = 35. 168 − 56 − 35 − 25 = 52.'),
  ('time-management','q6',2,'A realistic plan with space for rest is more likely to be followed. Overloaded plans collapse.'),
  ('time-management','q7',1,'Backward planning with mini-deadlines turns a large task into small steps and leaves a buffer.'),
  ('time-management','q8',3,'A good first action starts with a verb, takes about ten minutes and needs no further decisions.'),
  ('time-management','q9',3,'Shrinking the task lowers the barrier to starting, and starting often builds momentum.'),
  ('time-management','q10',1,'Out of sight and silent removes the temptation. A phone on the desk is still a distraction.'),
  ('time-management','q11',2,'Rest helps you think clearly in the exam. A short, calm review is better than exhausting yourself.'),
  ('time-management','q12',0,'A polite, clear no with an alternative protects your priority and the friendship.'),
  ('time-management','q13',1,'Deciding deliberately using your priorities is better than reacting. Some duties, like family responsibilities, may remain important.'),
  ('time-management','q14',3,'A review treats misses as information. Adjusting the plan is better than giving up or overloading it.'),
  ('time-management','q15',2,'One bad week is information, not failure. Restarting quickly with a plan you can follow keeps the habit alive.');
